param([string]$MigrationPath="$PSScriptRoot/../../sql/updates/world/2026_10_27_08_aluneth_initial_chest_retry.sql",[switch]$VerifyLive,[switch]$AddressSanitizer)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/aluneth-chest-retry"
function Block([string]$s,[string]$start){$a=$s.IndexOf($start);if($a -lt 0){throw "Missing native block $start"};$b=$s.IndexOf('{',$a)+1;$depth=1;while($depth){if($s[$b] -eq '{'){++$depth};if($s[$b] -eq '}'){--$depth};++$b};$s.Substring($a,$b-$a)}
function Section([string]$s,[string]$start,[string]$end){$a=$s.IndexOf($start);$b=$s.IndexOf($end,[Math]::Max(0,$a));if($a -lt 0 -or $b -le $a){throw "Native section missing $start"};$s.Substring($a,$b-$a)}
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories $out -Test {
 $migration=Get-Content $MigrationPath -Raw;$native=Get-Content "$PSScriptRoot/AlunethChestOriginal.json" -Raw|ConvertFrom-Json
 $filters=[ordered]@{smart_scripts='entryorguid IN(106756,249814,248572,248574) OR(action_type=50 AND action_param1=249814)';conditions='(SourceTypeOrReferenceId=22 AND SourceEntry IN(106756,249814,248572,248574)) OR(SourceTypeOrReferenceId=17 AND SourceEntry IN(211954,208011,218172)) OR(SourceTypeOrReferenceId=4 AND SourceGroup IN(249814,248572))';creature_template='entry=106756';creature='id=106756';gameobject_template='entry IN(249814,248572,248574,244556,251677)';gameobject='id IN(249814,248572,248574)';gameobject_loot_template='Entry IN(249814,248572)';spell_script_names='ABS(spell_id) IN(211954,208011,218172)';spell_scene='MiscValue IN(1244,1269)';spell_target_position='id=218172'}
 $setup='';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;`n"}
 function InsertRows($table,$fields,$rows){$values=@();foreach($row in $rows){$cell=@();foreach($field in $fields){$value=$row.$field;if($value -is [string]){$cell+="'"+$value.Replace("'","''")+"'"}elseif($null -eq $value){$cell+='NULL'}else{$cell+=[Convert]::ToString($value,[Globalization.CultureInfo]::InvariantCulture)}};$values+='('+($cell -join ',')+')'};'INSERT INTO '+$table+'('+($fields -join ',')+') VALUES'+($values -join ',')+';'}
 $restore='DELETE FROM smart_scripts WHERE entryorguid=106756 AND source_type=0;DELETE FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756;'+(InsertRows smart_scripts $native.fields $native.rows)+(InsertRows conditions $native.conditions_fields $native.conditions_rows)
 $setup+=$restore
 function Snapshot([string]$label,[switch]$Filtered){($filters.Keys|ForEach-Object {$where=if($Filtered){' WHERE '+$filters[$_]}else{''};"SELECT '$label-$_',a.* FROM $_ a$where;"}) -join "`n"}
 function Rows($rows,[string]$label){@($rows|Where-Object {$_ -like "$label`t*"}|ForEach-Object {$_.Substring($label.Length+1)}|Sort-Object -CaseSensitive)}
 function Signature($rows,[string]$label){(Rows $rows $label) -join "`n"}
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql,[switch]$Expected){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$db[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names --force 2> "$out/sql-stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior};$err=Get-Content "$out/sql-stderr.txt" -Raw;if($Expected){if($err -notmatch '1644 \(45000\)' -or @($err -split "`n"|Where-Object {$_ -match '^ERROR '}).Count -ne 1){throw 'Expected initial-chest refusal missing'}}elseif($code -or $err){throw 'Initial-chest TEMP/read-only query failed'};$rows}
 function Shapes([string]$label){"SELECT '$label-events',entryorguid,source_type,id,link,event_type,event_phase_mask,event_chance,event_flags,event_param1,event_param2,event_param3,event_param4,action_type,action_param1,action_param2,action_param3,target_type,target_x,target_y,target_z,target_o FROM smart_scripts WHERE entryorguid=106756 AND source_type=0 ORDER BY id;SELECT '$label-conditions',SourceGroup,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756 ORDER BY SourceGroup,ElseGroup,ConditionTypeOrReference,ConditionValue1;"}
 $rows=Query "$setup`n$(Snapshot 'original')`n$(Shapes 'native-original')`n$migration`n$(Snapshot 'first')`n$(Shapes 'native-fixed')`n$migration`n$(Snapshot 'second')`n$restore`n$(Snapshot 'normalized')"
 foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $rows "second-$t")){throw "Initial chest not idempotent: $t"};if((Signature $rows "original-$t") -cne (Signature $rows "normalized-$t")){throw "Initial chest changed unrelated row/field: $t"}}
 foreach($label in @('original','fixed')){foreach($kind in @('events','conditions')){[IO.File]::WriteAllLines("$out/$label-$kind.tsv",[string[]](Rows $rows "native-$label-$kind"))}}
 foreach($change in @("UPDATE creature_template SET ScriptName='custom' WHERE entry=106756;","UPDATE creature SET PhaseId='1' WHERE id=106756;",'UPDATE smart_scripts SET event_flags=257 WHERE entryorguid=106756 AND source_type=0 AND id=1;','UPDATE smart_scripts SET target_x=0 WHERE entryorguid=106756 AND source_type=0 AND id=2;','UPDATE smart_scripts SET action_param3=0 WHERE entryorguid=106756 AND source_type=0 AND id=3;','DELETE FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756 AND SourceGroup=2;',"UPDATE gameobject_template SET ScriptName='custom' WHERE entry=249814;","INSERT INTO smart_scripts(entryorguid,source_type,id,event_type,action_type,action_param1,comment) VALUES(999999,0,0,61,50,249814,'custom producer');")){
  $r=Query "$setup`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected;foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw "Refused initial chest changed $t"}}
 }
 foreach($change in @('UPDATE conditions SET ConditionTarget=0 WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756 AND SourceGroup=9;','UPDATE smart_scripts SET action_param3=4 WHERE entryorguid=106756 AND source_type=0 AND id=7;')){
  $r=Query "$setup`n$migration`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected;foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw "Refused applied initial chest changed $t"}}
 }
 if($VerifyLive){
  $sha=[Security.Cryptography.SHA1]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText((Resolve-Path $MigrationPath))).Replace("`r`n","`n")))).Replace('-','')}finally{$sha.Dispose()}
  $live=Query "SET SESSION TRANSACTION READ ONLY;SELECT 'update',hash,state FROM updates WHERE name='2026_10_27_08_aluneth_initial_chest_retry.sql';$(Snapshot 'live' -Filtered)"
  if($live -notcontains "update`t$hash`tRELEASED"){throw 'Live initial-chest updater/hash differs'}
  foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $live "live-$t")){throw "Live initial chest differs: $t"}}
 }
 $s=Get-Content "$repo/src/server/game/AI/SmartScripts/SmartScript.cpp" -Raw
 foreach($pair in @(@('Reset.inc','void SmartScript::OnReset('),@('UpdateTimer.inc','void SmartScript::UpdateTimer('),@('Events.inc','void SmartScript::ProcessEventsFor('))){[IO.File]::WriteAllText("$out/$($pair[0])",(Block $s $pair[1]).Replace('const SpellInfo*','void const*'))}
 [IO.File]::WriteAllText("$out/Phase.inc",(Block $s 'bool SmartScript::IsInPhase(')+(Block $s 'void SmartScript::SetPhase('))
 [IO.File]::WriteAllText("$out/Timer.inc",(Block $s 'void SmartScript::InitTimer(')+(Block $s 'void SmartScript::RecalcTimer('))
 $event=Block $s 'void SmartScript::ProcessEvent(';[IO.File]::WriteAllText("$out/EventPrefix.inc",$event.Substring($event.IndexOf('{')+1,$event.IndexOf('    switch (e.GetEventType())')-$event.IndexOf('{')-1))
 [IO.File]::WriteAllText("$out/SelectedEvents.inc",(Section $event '        case SMART_EVENT_LINK:' '        case SMART_EVENT_UPDATE_OOC:')+"case SMART_EVENT_RESET:`nProcessAction(e,unit,var0,var1,bvar,spell,gob);break;`n")
 $nativeResetCase=Section $event '        case SMART_EVENT_RESET:' '        case SMART_EVENT_IS_BEHIND_TARGET:'
 if($nativeResetCase -notmatch 'ProcessAction\(e, unit, var0, var1, bvar, spell, gob\);'){throw 'Native reset dispatch changed'}
 $action=Block $s 'void SmartScript::ProcessAction(';[IO.File]::WriteAllText("$out/ActionPrefix.inc",$action.Substring($action.IndexOf('{')+1,$action.IndexOf('    switch (e.GetActionType())')-$action.IndexOf('{')-1))
 [IO.File]::WriteAllText("$out/SummonGo.inc",(Section $action '        case SMART_ACTION_SUMMON_GO:' '        case SMART_ACTION_KILL_UNIT:'))
 [IO.File]::WriteAllText("$out/SetPhaseAction.inc",(Section $action '        case SMART_ACTION_SET_EVENT_PHASE:' '        case SMART_ACTION_INC_EVENT_PHASE:'))
 $a=$action.IndexOf('    if (e.link && e.link != e.event_id)');[IO.File]::WriteAllText("$out/Links.inc",$action.Substring($a,$action.LastIndexOf('}')-$a))
 $s=Get-Content "$repo/src/server/game/AI/SmartScripts/SmartScriptMgr.h" -Raw;$enums='';foreach($name in @('SMART_EVENT','SMART_ACTION','SMARTAI_TARGETS','SmartScriptType','SmartEventFlags','SMART_EVENT_PHASE')){$enums+=(Block $s "enum $name`r`n")+';'};[IO.File]::WriteAllText("$out/NativeEnums.inc",$enums)
 [IO.File]::WriteAllText("$out/CastFlags.inc",(Block $s 'enum SmartCastFlags')+';');[IO.File]::WriteAllText("$out/SummonFlags.inc",(Block $s 'enum SmartSummonGameObjectFlags')+';')
 $s=Get-Content "$repo/src/server/game/AI/SmartScripts/SmartScriptMgr.cpp" -Raw
 [IO.File]::WriteAllText("$out/SummonValidation.inc",(Section $s '        case SMART_ACTION_SUMMON_GO:' '        case SMART_ACTION_ADD_ITEM:'))
 $s=Get-Content "$repo/src/server/game/Conditions/ConditionMgr.cpp" -Raw
 [IO.File]::WriteAllText("$out/Conditions.inc",(Section $s '        case CONDITION_NEAR_GAMEOBJECT:' '        case CONDITION_OBJECT_ENTRY:')+(Section $s '        case CONDITION_SCENARION_STEP:' '        case CONDITION_REALM_ACHIEVEMENT:'))
 [IO.File]::WriteAllText("$out/ElseGroups.inc",(Block $s 'bool ConditionMgr::IsObjectMeetToConditionList('));[IO.File]::WriteAllText("$out/GetConditions.inc",(Block $s 'ConditionList ConditionMgr::GetConditionsForSmartEvent('));[IO.File]::WriteAllText("$out/EventConditions.inc",(Block $s 'bool ConditionMgr::IsObjectMeetingSmartEventConditions('))
 $s=Get-Content "$repo/src/server/game/Grids/Notifiers/GridNotifiers.h" -Raw;[IO.File]::WriteAllText("$out/NearestClass.inc",(Block $s 'class NearestGameObjectEntryInObjectRangeCheck')+';');[IO.File]::WriteAllText("$out/SearcherClass.inc",'template<class Check>'+(Block $s 'struct GameObjectLastSearcher')+';')
 $s=Get-Content "$repo/src/server/game/Grids/Notifiers/GridNotifiers.cpp" -Raw;[IO.File]::WriteAllText("$out/NearestBody.inc",(Block $s 'NearestGameObjectEntryInObjectRangeCheck::NearestGameObjectEntryInObjectRangeCheck(')+(Block $s 'bool NearestGameObjectEntryInObjectRangeCheck::operator()('))
 $s=Get-Content "$repo/src/server/game/Grids/Notifiers/GridNotifiersImpl.h" -Raw;[IO.File]::WriteAllText("$out/SearcherVisit.inc",'template<class Check>'+(Block $s 'void Trinity::GameObjectLastSearcher<Check>::Visit(GameObjectMapType'))
 $s=Get-Content "$repo/src/server/game/Entities/Object/Object.cpp" -Raw;[IO.File]::WriteAllText("$out/WithinMap.inc",(Block $s 'bool WorldObject::IsWithinDistInMap(').Replace(' /*=false*/',''))
 [IO.File]::WriteAllText("$out/FindNearest.inc",(Block $s 'GameObject* WorldObject::FindNearestGameObject('))
 $s=Get-Content "$repo/src/server/game/AI/ScriptedAI/ScriptedCreature.h" -Raw;[IO.File]::WriteAllText("$out/Closest.inc",(Block $s 'inline GameObject* GetClosestGameObjectWithEntry('))
